func ParseMemory(s string) (int64, error) {
	units := map[string]int64{"Ki": 1 << 10, "Mi": 1 << 20, "Gi": 1 << 30, "Ti": 1 << 40}
	for suf, mult := range units {
		if strings.HasSuffix(s, suf) {
			n, err := strconv.ParseInt(strings.TrimSuffix(s, suf), 10, 64)
			if err != nil {
				return 0, err
			}
			return n * mult, nil
		}
	}
	return strconv.ParseInt(s, 10, 64) // plain byte count
}
